begin;
select plan(17);
select ok((select relrowsecurity from pg_class where oid='public.face_attendance_sessions'::regclass),'RLS remains enabled');
select ok(not has_table_privilege('anon','public.face_attendance_sessions','SELECT'),'anon cannot read face sessions');
select ok(not has_table_privilege('authenticated','public.face_attendance_sessions','SELECT'),'browser cannot read face sessions');
select ok(not has_table_privilege('authenticated','public.face_attendance_sessions','INSERT'),'browser cannot issue face sessions');
select ok(not has_table_privilege('authenticated','public.biometric_templates','SELECT'),'browser cannot read templates');
select ok(not has_table_privilege('authenticated','public.face_model_versions','SELECT'),'browser cannot read model registry');
select ok(has_table_privilege('service_role','public.face_attendance_sessions','SELECT'),'backend can read face sessions');
select ok(has_table_privilege('service_role','public.face_attendance_sessions','INSERT'),'backend can issue face sessions');
select ok(not has_function_privilege('authenticated','public.face_attendance_issue(text,text,text)','EXECUTE'),'browser cannot call issuance');
select ok(not has_function_privilege('anon','public.face_attendance_claim(text,uuid,uuid)','EXECUTE'),'anonymous cannot claim');
select ok(not has_function_privilege('authenticated','public.face_attendance_finish(text,uuid,uuid,jsonb)','EXECUTE'),'browser cannot finalize attendance');
select ok(not has_function_privilege('authenticated','public.face_attendance_fail(text,uuid,uuid,text)','EXECUTE'),'browser cannot change final state');
select ok(not has_function_privilege('authenticated','private.face_attendance_session(text,uuid)','EXECUTE'),'browser cannot call private session lookup');
select ok(has_function_privilege('service_role','public.face_attendance_finish(text,uuid,uuid,jsonb)','EXECUTE'),'backend can commit attendance');
select ok(not (select prosecdef from pg_proc where oid='public.face_attendance_finish(text,uuid,uuid,jsonb)'::regprocedure),'commit uses security invoker');
select ok(not exists(select 1 from pg_policies where tablename='face_attendance_sessions'),'no biometric browser policy');
select ok((select count(*)=4 from pg_proc join pg_namespace n on n.oid=pronamespace where n.nspname='public' and proname like 'face_attendance_%' and not prosecdef),'all attendance RPCs are security invoker');
select * from finish();
rollback;
